mapper.select:
/* LoginMapper.selectUserMblHmacConflict */
SELECT COUNT(1)
FROM TB_USER A
WHERE A.CMPNY_CD     = #{cmpnyCd}
  AND A.MBL_NO_HMAC = #{mblNoHmac}
  AND A.USER_CD != #{userCd}

mapper.update:
/* LoginMapper.activateAccount */
UPDATE TB_USER
SET ACCOUNT_STATUS = '01'
    , UPDATE_NO    = #{userCd}
    , UPDATE_DATE  = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}
  AND ACCOUNT_STATUS = '04'

/* LoginMapper.updateUserMblNo */
UPDATE TB_USER
SET MBL_NO_ENC   = #{mblNoEnc}
    , MBL_NO_HMAC = #{mblNoHmac}
    , MBL_NO_LAST4 = #{mblNoLast4}
    , UPDATE_NO   = #{userCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}

    /* LoginMapper.updateUserPwdReset */
    UPDATE TB_USER
	SET PWD_LOCK_YN 			= 'N'
		, PWD_FAIL_CNT 			= 0
		, PWD_LOCK_EXPIRE_DTIME = null
		, UPDATE_NO     		= 'SYSTEM'
	    , UPDATE_DATE   		= NOW()
	WHERE CMPNY_CD = #{cmpnyCd}
	  AND USER_CD  = #{userCd}

mapper.select:
/* LoginMapper.selectPwdLockRemainMinutes */
SELECT CEIL(TIMESTAMPDIFF(SECOND, NOW(), PWD_LOCK_EXPIRE_DTIME) / 60)
FROM TB_USER
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD = #{userCd}
  AND PWD_LOCK_YN = 'Y'
  AND PWD_LOCK_EXPIRE_DTIME IS NOT NULL
  AND PWD_LOCK_EXPIRE_DTIME > NOW()

    /* LoginMapper.lockUserRow */
    SELECT 1
	FROM TB_USER
	WHERE CMPNY_CD = #{cmpnyCd}
	  AND USER_CD  = #{userCd}
	FOR UPDATE

mapper.update:
    /* LoginMapper.revokeActiveToken */
    UPDATE prafta.TB_AUTH_TOKEN
	SET REVOKED_YN='Y',
	    REVOKED_DTIME=NOW(),
	    UPDATE_NO=#{userCd},
	    UPDATE_DATE=NOW()
	WHERE CMPNY_CD=#{cmpnyCd}
	  AND USER_CD=#{userCd}
	  AND CLIENT_TYPE=#{clientType}
	  AND REVOKED_YN='N'
	  AND EXPIRE_DTIME > NOW()

mapper.insert:
    /* LoginMapper.insertAuthToken */
    INSERT INTO TB_AUTH_TOKEN (
	    CMPNY_CD
	    , USER_CD
	    , TOKEN_ID
	    , LOGIN_ID
	    , CLIENT_TYPE
	    , REFRESH_TOKEN_HASH
	    , ISSUED_DTIME
	    , EXPIRE_DTIME
	    , REVOKED_YN
	    , REVOKED_DTIME
	    , INSERT_NO
	    , INSERT_DATE
	) VALUES (
	    #{cmpnyCd}
	    , #{userCd}
	    , #{tokenId}
	    , #{loginId}
	    , #{clientType}
	    , #{refreshTokenHash}
	    , NOW()
	    , DATE_ADD(NOW(), INTERVAL #{expireDtime} DAY)
	    , 'N'
	    , NULL,
	    #{userCd}
	    , NOW()
	)

