    /* LoginMapper.updateUserLastLoginDtime */

    UPDATE TB_USER
    SET LAST_LOGIN_DTIME = NOW()
    	, UPDATE_NO = 'SYSTEM'
    	, UPDATE_DATE = NOW()
	WHERE CMPNY_CD = #{cmpnyCd}
	  AND USER_CD  = #{userCd}

mapper.select:
/* LoginMapper.selectUserCd */
SELECT CONCAT(DATE_FORMAT(NOW(), '%Y%m'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'USER_CD'))
FROM DUAL

/* LoginMapper.selectNodeHasAdmin */
SELECT COUNT(1)
FROM TB_SITE_NODE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND A.NODE_CD  = #{nodeCd}
  AND (
        NULLIF(TRIM(A.MAIN_ADMIN_CD), '') IS NOT NULL
     OR NULLIF(TRIM(A.SUB_ADMIN_CD), '')  IS NOT NULL
      )

/* LoginMapper.selectMirrorSiteCnt */
SELECT COUNT(1)
FROM TB_SITE A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD  = #{siteCd}
  AND A.LINK_SRC_CMPNY_CD IS NOT NULL

mapper.insert:
/* LoginMapper.insertUserInfo */
INSERT INTO TB_USER (
    CMPNY_CD
    , USER_CD
    , USER_ID
    , USER_NM
    , USER_PW
    , SITE_CD
    , NODE_CD
    , AUTH_CD
    , MBL_NO_ENC
    , MBL_NO_HMAC
    , MBL_NO_LAST4
    , EMAIL_ENC
    , EMAIL_HMAC
    , EMAIL_DOMAIN
    , GENDER
    , BIRTH_DT_ENC
    , USE_YN

    , ACCOUNT_STATUS

    , PWD_CHG_DTIME
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
    #{cmpnyCd}
    , #{userCd}
    , #{userId}
    , #{userNm}
    , #{userPw}
    , #{siteCd}
    , #{nodeCd}

    , '99999'					
    , #{mblNoEnc}
    , #{mblNoHmac}
    , #{mblNoLast4}
    , #{emailEnc}
    , #{emailHmac}
    , #{emailDomain}
    , #{gender}
    , #{birthDtEnc}

    , 'N'
    , '06'				
    , NOW()				
    , 'SYSTEM'
    , NOW()
    , 'SYSTEM'
    , NOW()
)

mapper.select:
/* LoginMapper.selectDailyUserIdExists */
SELECT COUNT(1)
FROM TB_DAILY_USER
WHERE USER_ID = #{userId}
  AND USE_YN  = 'Y'

mapper.update:
/* LoginMapper.updateRejectedUserForRejoin */
UPDATE TB_USER
SET USER_ID        = #{userId}
    , USER_NM      = #{userNm}
    , USER_PW      = #{userPw}
    , SITE_CD      = #{siteCd}
    , NODE_CD      = #{nodeCd}

    , AUTH_CD      = '99999'
    , MBL_NO_ENC   = #{mblNoEnc}
    , MBL_NO_HMAC  = #{mblNoHmac}
    , MBL_NO_LAST4 = #{mblNoLast4}
    , EMAIL_ENC    = #{emailEnc}
    , EMAIL_HMAC   = #{emailHmac}
    , EMAIL_DOMAIN = #{emailDomain}
    , GENDER       = #{gender}
    , BIRTH_DT_ENC = #{birthDtEnc}

    , USE_YN       = 'N'
    , ACCOUNT_STATUS = '06'

    , PWD_LOCK_YN  = 'N'
    , PWD_FAIL_CNT = 0
    , PWD_LOCK_EXPIRE_DTIME = NULL
    , PWD_CHG_DTIME = NOW()
    , WITHDRAWAL_DATE = NULL

    , UPDATE_NO    = 'REJOIN'
    , UPDATE_DATE  = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND USER_CD  = #{userCd}
  AND ACCOUNT_STATUS = '07'

mapper.select:
/* LoginMapper.selectSelfJoinVerifiedSmsId */
SELECT S.SMS_ID
FROM TB_SMS_AUTH_CODE S
WHERE S.MBL_NO_HMAC = #{mblNoHmac}
  AND S.PURPOSE_CD  = 'SELF_JOIN'
  AND S.VERIFIED_YN = 'Y'
  AND S.UPDATE_DATE  >=  DATE_SUB(NOW(), INTERVAL 30 MINUTE)

  AND S.AUTH_CD = #{certNo}

ORDER BY S.UPDATE_DATE DESC
LIMIT 1

mapper.update:
/* LoginMapper.deactivateOtherUserSiteAuth */
UPDATE TB_USER_SITE_AUTH
   SET USE_YN      = 'N'
     , UPDATE_NO   = 'SYSTEM'
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}
   AND SITE_CD != #{siteCd}
   AND USE_YN   = 'Y'

    /* LoginMapper.revokeActiveTokenByClient */
	UPDATE TB_AUTH_TOKEN
       SET REVOKED_YN    = 'Y'
         , REVOKED_DTIME = NOW()
         , UPDATE_NO     = #{userCd}
         , UPDATE_DATE   = NOW()
     WHERE CMPNY_CD      = #{cmpnyCd}
       AND USER_CD       = #{userCd}
       AND CLIENT_TYPE   = #{clientType}
       AND REVOKED_YN    = 'N'
       AND EXPIRE_DTIME  > NOW()

       AND DEVICE_ID     = #{deviceId}

/* LoginMapper.revokeAllActiveTokens */
UPDATE TB_AUTH_TOKEN
   SET REVOKED_YN    = 'Y'
     , REVOKED_DTIME = NOW()
     , UPDATE_NO     = #{userCd}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD      = #{cmpnyCd}
   AND USER_CD       = #{userCd}
   AND REVOKED_YN    = 'N'
   AND EXPIRE_DTIME  > NOW()

mapper.insert:
/* LoginMapper.insertUserSiteAuth */
INSERT INTO TB_USER_SITE_AUTH (
	CMPNY_CD
	, USER_CD
	, SITE_CD
	, USE_YN
	, INSERT_NO
	, INSERT_DATE
	, UPDATE_NO
	, UPDATE_DATE
) VALUES (
	#{cmpnyCd}
	, #{userCd}
	, #{siteCd}
	, 'Y'
	, #{userCd}
	, NOW()
	, #{userCd}
	, NOW()
)

ON DUPLICATE KEY UPDATE
	USE_YN        = 'Y'
	, UPDATE_NO   = #{userCd}
	, UPDATE_DATE = NOW()

/* LoginMapper.insertTermsUserAgrMgmt */
INSERT INTO TB_TERMS_USER_AGR_MGMT (
	CMPNY_CD
	, USER_CD
	, TERMS_ID
	, TERMS_VERSION
	, AGR_YN
	, INSERT_NO
	, INSERT_DATE
)
VALUES (
	#{cmpnyCd}
	, #{userCd}
	, #{termsId}
	, #{termsVersion}
	, #{agrYn}
	, #{userCd}
	, NOW()
)

ON DUPLICATE KEY UPDATE
	AGR_YN        = #{agrYn}
	, INSERT_NO   = #{userCd}
	, INSERT_DATE = NOW()

/* LoginMapper.upsertUserDevice */
INSERT INTO TB_USER_DEVICE (
      DEVICE_UUID
    , CMPNY_CD
    , USER_CD
    , DEVICE_TYPE
    , DEVICE_MODEL
    , OS_VERSION
    , APP_VERSION
    , LAST_LOGIN_DTIME
    , LAST_LOGIN_IP
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{deviceUuid}
    , #{cmpnyCd}
    , #{userCd}
    , IFNULL(#{deviceType}, 'UNKNOWN')
    , #{deviceModel}
    , #{osVersion}
    , #{appVersion}
    , NOW()
    , #{loginIp}
    , 'N'
    , #{insertNo}
    , NOW()
)
ON DUPLICATE KEY UPDATE
      CMPNY_CD         = VALUES(CMPNY_CD)
    , USER_CD          = VALUES(USER_CD)
    , DEVICE_TYPE      = VALUES(DEVICE_TYPE)
    , DEVICE_MODEL     = VALUES(DEVICE_MODEL)
    , OS_VERSION       = VALUES(OS_VERSION)
    , APP_VERSION      = VALUES(APP_VERSION)
    , LAST_LOGIN_DTIME = VALUES(LAST_LOGIN_DTIME)
    , LAST_LOGIN_IP    = VALUES(LAST_LOGIN_IP)
    , DEL_YN           = 'N'
    , UPDATE_NO        = #{insertNo}
    , UPDATE_DATE      = NOW()

/* LoginMapper.insertDeviceLoginHist */
INSERT INTO TB_USER_DEVICE_LOGIN_HIST (
      DEVICE_LOGIN_NO
    , CMPNY_CD
    , DEVICE_UUID
    , USER_CD
    , DEVICE_TYPE
    , DEVICE_MODEL
    , OS_VERSION
    , APP_VERSION
    , CLIENT_TYPE
    , LOGIN_IP
    , LOGIN_DTIME
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      CONCAT(DATE_FORMAT(NOW(), '%Y%m'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DEVICE_LOGIN_NO'))
    , #{cmpnyCd}
    , #{deviceUuid}
    , #{userCd}
    , #{deviceType}
    , #{deviceModel}
    , #{osVersion}
    , #{appVersion}
    , #{clientType}
    , #{loginIp}
    , NOW()
    , #{insertNo}
    , NOW()
)

