/* LoginMapper.deactivateOtherUserDevices */

UPDATE TB_USER_DEVICE
   SET DEL_YN      = 'Y'
     , UPDATE_NO   = #{userCd}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND USER_CD     = #{userCd}
   AND DEVICE_UUID != #{deviceUuid}
   AND DEL_YN      = 'N'

mapper.select:
/* LoginMapper.selectDeviceOwner */
SELECT USER_CD
  FROM TB_USER_DEVICE
 WHERE DEVICE_UUID = #{deviceUuid}
 LIMIT 1

mapper.insert:
/* LoginMapper.insertOccupancyAnomaly */
INSERT INTO TB_USER_DEVICE_OCCUPANCY_ANOMALY (
      ANOMALY_NO
    , CMPNY_CD
    , DEVICE_UUID
    , PREV_USER_CD
    , NEW_USER_CD
    , CLIENT_TYPE
    , LOGIN_IP
    , DETECTED_DTIME
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      CONCAT(DATE_FORMAT(NOW(), '%Y%m'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'DEVICE_ANOMALY_NO'))
    , #{cmpnyCd}
    , #{deviceUuid}
    , #{prevUserCd}
    , #{newUserCd}
    , #{clientType}
    , #{loginIp}
    , NOW()
    , #{newUserCd}
    , NOW()
)

mapper.update:
/* LoginMapper.clearPushTokenForDevice */

UPDATE TB_USER_DEVICE
   SET PUSH_TOKEN  = NULL
     , UPDATE_NO   = #{userCd}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD    = #{cmpnyCd}
   AND DEVICE_UUID = #{deviceUuid}
   AND USER_CD     = #{userCd}
